<template><div class="post-item" :style="{animationDelay:`${Math.min(index,6)*.04}s`}" @click="router.push(`/post/${post.id}`)"><div class="post-item-icon"><AvatarIcon v-if="post.author_avatar" :type="post.author_avatar" :size="56"/><span v-else class="post-item-icon-placeholder">◉</span></div><div class="post-item-content"><div class="post-item-title"><span class="post-item-category">【{{categoryLabel}}】</span><span v-if="post.is_grave" class="post-item-grave">坟贴</span><span class="post-item-text">{{post.title}}</span></div><div v-if="post.image_url" class="post-item-thumbnail"><img :src="post.image_url" alt="post thumbnail" loading="lazy"></div><div v-if="post.author" class="post-item-meta"><span>{{post.author}}</span><span>{{post.created_at}}</span><span>{{post.reply_count||0}} {{t('replies')}}</span><span>{{post.like_count||0}} {{t('likes')}}</span></div></div></div></template>
<script setup>import {computed} from 'vue';import {useRouter} from 'vue-router';import {useLang} from '../contexts/app';import AvatarIcon from './AvatarIcon.vue';import './PostItem.css';const props=defineProps({post:Object,index:{type:Number,default:0}});const router=useRouter();const {t}=useLang();const map={'讨论':'catDiscussion','探灵':'catExplore','灵异':'catParanormal','求助':'catHelp','分享':'catShare','直播':'catLive','语c':'catLive','OC投稿':'catOC'};const categoryLabel=computed(()=>t(map[props.post.category]||'catDiscussion')||props.post.category);</script>
